#!/usr/bin/env python3
"""Fill a Word (.docx) template from a JSON data file, end-to-end, and self-verify.

Handles EVERY place a {{PLACEHOLDER}} can hide and every way it can break:
  * placeholders split across multiple runs (Word does this constantly)
  * body paragraphs, tables, and tables NESTED inside table cells (any depth)
  * headers and footers (they are NOT in doc.paragraphs)
  * {{IF_X}} ... {{END_IF_X}} conditional blocks that span MULTIPLE paragraphs
  * data keys that differ in case/spacing/underscores from the placeholder name
    (keys are matched case-insensitively, ignoring non-alphanumeric characters;
     nested JSON objects are flattened, so {"pay":{"Base Salary":100}} fills
     {{BASE_SALARY}})

After saving it RE-OPENS the output and lists any {{...}} that remain; if any
remain it exits non-zero so you never falsely report success.

Usage:
    python3 fill_template.py <template.docx> <data.json> <output.docx>
"""
import re, json, sys
from docx import Document

PH     = re.compile(r"\{\{\s*([A-Za-z0-9_]+)\s*\}\}")
IF_RE  = re.compile(r"\{\{\s*IF_([A-Za-z0-9_]+)\s*\}\}")
END_RE = re.compile(r"\{\{\s*END_IF_([A-Za-z0-9_]+)\s*\}\}")
FALSE  = {"", "no", "n", "false", "0", "none", "off"}


def norm(s):
    return re.sub(r"[^a-z0-9]", "", str(s).lower())


def flatten(obj, out):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                flatten(v, out)
            else:
                out[norm(k)] = v
    elif isinstance(obj, list):
        for v in obj:
            flatten(v, out)
    return out


def truthy(v):
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    return str(v).strip().lower() not in FALSE


def set_text(p, t):
    if p.runs:
        p.runs[0].text = t
        for r in p.runs[1:]:
            r.text = ""
    elif t:
        p.add_run(t)


def fill_para(p, data):
    if "{{" not in p.text:
        return
    new = PH.sub(lambda m: str(data[norm(m.group(1))]) if norm(m.group(1)) in data else m.group(0), p.text)
    if new != p.text:
        set_text(p, new)


def cond_val(data, name):
    for k in (name, name + "_PACKAGE", name + "_INCLUDED", "INCLUDE_" + name):
        if norm(k) in data:
            return data[norm(k)]
    return None  # unknown condition -> keep content, just strip the markers


def process(paras, data):
    keep_stack = []
    for p in paras:
        inside = all(keep_stack) if keep_stack else True
        if IF_RE.search(p.text):
            cv = cond_val(data, IF_RE.search(p.text).group(1))
            keep = inside and (True if cv is None else truthy(cv))
            set_text(p, IF_RE.sub("", p.text, count=1))
            keep_stack.append(keep)
            if not keep:
                set_text(p, "")
                continue
        if END_RE.search(p.text):
            was = all(keep_stack) if keep_stack else True
            if keep_stack:
                keep_stack.pop()
            set_text(p, END_RE.sub("", p.text, count=1) if was else "")
            if not was:
                continue
        if not (all(keep_stack) if keep_stack else True):
            set_text(p, "")
            continue
        fill_para(p, data)


def walk(t, data):
    for row in t.rows:
        for c in row.cells:
            process(c.paragraphs, data)
            for n in c.tables:
                walk(n, data)


def fill(tmpl, data, out):
    doc = Document(tmpl)
    process(doc.paragraphs, data)
    for t in doc.tables:
        walk(t, data)
    for s in doc.sections:
        for hf in (s.header, s.footer, s.first_page_header, s.first_page_footer):
            process(hf.paragraphs, data)
            for t in hf.tables:
                walk(t, data)
    doc.save(out)


def leftover(out):
    doc = Document(out)
    parts = [p.text for p in doc.paragraphs]

    def wt(t):
        for r in t.rows:
            for c in r.cells:
                parts.extend(x.text for x in c.paragraphs)
                for n in c.tables:
                    wt(n)

    for t in doc.tables:
        wt(t)
    for s in doc.sections:
        for hf in (s.header, s.footer):
            parts.extend(p.text for p in hf.paragraphs)
    return sorted(set(re.findall(r"\{\{[^{}]+\}\}", "\n".join(parts))))


def main():
    if len(sys.argv) != 4:
        print(__doc__)
        sys.exit(1)
    tmpl, data_path, out = sys.argv[1:4]
    with open(data_path) as f:
        data = flatten(json.load(f), {})
    fill(tmpl, data, out)
    rem = leftover(out)
    if rem:
        print(f"ERROR: {len(rem)} unreplaced placeholder(s) remain: {rem}")
        print("Add a JSON key for each (name inside the braces) and re-run.")
        sys.exit(1)
    print(f"OK: wrote {out} with 0 remaining placeholders.")


if __name__ == "__main__":
    main()
